1	import { failureLine, runEntire } from './entire-cli.mjs'
2	import { workspaceHost } from './hosts.mjs'
3	import { resolveFocusedWorkspace } from './workspace.mjs'
4	
5	const STEPS = [
6	  { label: 'Entire CLI', args: ['--version'], summarize: (out) => out.trim().split('\n')[0] },
7	  {
8	    label: 'Repo',
9	    args: ['status', '--json'],
10	    summarize: (out) => {
11	      const status = JSON.parse(out)
12	      if (!status.enabled) return 'Entire is not enabled here'
13	      return `enabled · agents: ${(status.agents ?? []).join(', ') || 'none'}`
14	    }
15	  },
16	  // A branch without a trail is normal, so this step reports instead of failing the check.
17	  // Until we have real fixtures, list the keys so the first run shows the trail's JSON shape.
18	  {
19	    label: 'Trail',
20	    args: ['trail', 'show', '--json'],
21	    optional: true,
22	    summarize: (out) => `found (${Object.keys(JSON.parse(out)).join(', ')})`
23	  }
24	]
25	
26	// "Entire: Check connection" walks every link the plugin depends on and reports one line per link.
27	export async function checkConnection(orca, { signal } = {}) {
28	  const lines = [`Orca host API ${orca.api.major}.${orca.api.minor} · Node ${process.version} on ${process.platform}`]
29	  const report = (line) => [...lines, line].join('\n')
30	
31	  let workspace
32	  try {
33	    workspace = await resolveFocusedWorkspace(orca, { signal })
34	  } catch (error) {
35	    return report(`✗ Workspace lookup failed: ${error.message}`)
36	  }
37	  const { context, path, via, candidates } = workspace
38	  if (!context) return report('✗ No workspace is focused')
39	  if (!path) {
40	    // Without a terminal, only branch and name identify the workspace, and many repos share "main".
41	    const why = candidates.length > 0 ? `${candidates.length} workspaces match it` : 'no workspace matches it'
42	    return report(`✗ ${context.displayName} on ${context.branch}: ${why}. Open a terminal in it and try again.`)
43	  }
44	  const host = workspaceHost(path)
45	  const where = host.kind === 'wsl' ? `WSL ${host.distro} ${host.path}` : path
46	  lines.push(`✓ ${context.displayName} on ${context.branch} → ${where} (via ${via})`)
47	
48	  for (const step of STEPS) {
49	    let result
50	    try {
51	      result = await runEntire(host, step.args, { signal })
52	    } catch (error) {
53	      return report(`✗ ${step.label}: ${error.message}`)
54	    }
55	    if (result.code !== 0) {
56	      lines.push(`${step.optional ? '·' : '✗'} ${step.label}: ${failureLine(result)}`)
57	      if (step.optional) continue
58	      break
59	    }
60	    try {
61	      lines.push(`✓ ${step.label}: ${step.summarize(result.stdout)} (${result.ms} ms)`)
62	    } catch {
63	      lines.push(`✗ ${step.label}: unexpected output: ${result.stdout.slice(0, 120)}`)
64	      break
65	    }
66	  }
67	  return lines.join('\n')
68	}
