1	// Orca reports WSL workspaces as UNC paths, while the plugin worker always runs on the desktop host.
2	// Entire has to run where the repo and its login live, so each workspace path maps to a host.
3	
4	const WSL_UNC = /^\\\\wsl(?:\.localhost|\$)\\([^\\]+)(\\.*)?$/i
5	
6	export function workspaceHost(workspacePath) {
7	  const match = WSL_UNC.exec(workspacePath.replaceAll('/', '\\'))
8	  if (!match) return { kind: 'local', path: workspacePath }
9	  return { kind: 'wsl', distro: match[1], path: (match[2] ?? '\\').replaceAll('\\', '/') }
10	}
11	
12	export function entireCommand(host, args) {
13	  if (host.kind === 'wsl') {
14	    // A login shell puts ~/.local/bin on PATH; "$@" passes each argument through without re-parsing.
15	    return {
16	      command: 'wsl.exe',
17	      args: ['-d', host.distro, '--cd', host.path, '-e', 'bash', '-lc', 'exec entire "$@"', 'entire', ...args]
18	    }
19	  }
20	  return { command: 'entire', args, cwd: host.path }
21	}
